import re
from datetime import date

_MONTH = (
    r"(jan(?:uary)?|feb(?:ruary)?|mar(?:ch)?|apr(?:il)?|may|jun(?:e)?|"
    r"jul(?:y)?|aug(?:ust)?|sep(?:t(?:ember)?)?|oct(?:ober)?|"
    r"nov(?:ember)?|dec(?:ember)?)"
)
_MONTH_NUM = {
    "jan": 1, "feb": 2, "mar": 3, "apr": 4, "may": 5, "jun": 6,
    "jul": 7, "aug": 8, "sep": 9, "oct": 10, "nov": 11, "dec": 12,
}

_YMD = re.compile(r"([0-9]{4})([-/.])([0-9]{1,2})\2([0-9]{1,2})")
_DMY = re.compile(r"([0-9]{1,2})([-/.])([0-9]{1,2})\2([0-9]{4})")
_D_MON_Y = re.compile(
    r"([0-9]{1,2})(?:st|nd|rd|th)?\s+" + _MONTH + r"\.?,?\s+([0-9]{4})",
    re.IGNORECASE,
)
_MON_D_Y = re.compile(
    _MONTH + r"\.?\s+([0-9]{1,2})(?:st|nd|rd|th)?,?\s+([0-9]{4})",
    re.IGNORECASE,
)


def _build(y: int, m: int, d: int) -> str:
    try:
        return date(y, m, d).isoformat()
    except ValueError:
        return "INVALID"


def _month_number(name: str) -> int:
    return _MONTH_NUM[name.lower()[:3]]


def parse(s: str) -> str:
    if not isinstance(s, str):
        return "INVALID"

    s = " ".join(s.split())  # trim and collapse internal whitespace

    m = _YMD.fullmatch(s)
    if m:
        y, _, mo, d = m.groups()
        return _build(int(y), int(mo), int(d))

    # Ambiguous numeric dates with the year last are read as DD/MM/YYYY,
    # per the expected output for '05/03/2024' -> '2024-03-05'.
    m = _DMY.fullmatch(s)
    if m:
        d, _, mo, y = m.groups()
        return _build(int(y), int(mo), int(d))

    # Textual: '5th March 2024', '5 Mar. 2024'
    m = _D_MON_Y.fullmatch(s)
    if m:
        d, mon, y = m.groups()
        return _build(int(y), _month_number(mon), int(d))

    # Textual: 'March 5th, 2024', 'Mar 5 2024'
    m = _MON_D_Y.fullmatch(s)
    if m:
        mon, d, y = m.groups()
        return _build(int(y), _month_number(mon), int(d))

    return "INVALID"

import re
from datetime import date

_MONTHS = {
    "jan": 1, "january": 1,
    "feb": 2, "february": 2,
    "mar": 3, "march": 3,
    "apr": 4, "april": 4,
    "may": 5,
    "jun": 6, "june": 6,
    "jul": 7, "july": 7,
    "aug": 8, "august": 8,
    "sep": 9, "sept": 9, "september": 9,
    "oct": 10, "october": 10,
    "nov": 11, "november": 11,
    "dec": 12, "december": 12,
}

# Longest names first so the alternation prefers full names over abbreviations.
_WEEKDAY_NAMES = [
    "monday", "tuesday", "wednesday", "thursday", "friday", "saturday", "sunday",
    "mon", "tues", "tue", "wed", "thurs", "thur", "thu", "fri", "sat", "sun",
]
_WEEKDAY_PREFIX = re.compile(
    r"^(?:" + "|".join(_WEEKDAY_NAMES) + r")\.?,?\s+",
    re.IGNORECASE | re.ASCII,
)


def _iso(y: int, m: int, d: int):
    """Return 'YYYY-MM-DD' if (y, m, d) is a real calendar date, else None."""
    try:
        return date(y, m, d).isoformat()
    except (ValueError, OverflowError):
        return None


def _numeric(a: str, b: str, y: str):
    """Interpret a/b/y. Prefer day-first (dd/mm/yyyy); fall back to month-first if day-first is impossible."""
    a_i, b_i, y_i = int(a), int(b), int(y)
    return _iso(y_i, b_i, a_i) or _iso(y_i, a_i, b_i)


def _month_num(name: str):
    return _MONTHS.get(name.lower())


def parse(s: str) -> str:
    if not isinstance(s, str):
        return "INVALID"

    t = re.sub(r"\s+", " ", s.strip())

    # Drop an optional leading weekday: "Tuesday, March 5, 2024", "Tue. 5 Mar 2024"
    t = _WEEKDAY_PREFIX.sub("", t, count=1).strip()
    if not t:
        return "INVALID"

    # YYYY-MM-DD, YYYY/MM/DD, YYYY.MM.DD (also single-digit month/day)
    m = re.fullmatch(r"([0-9]{4})[-/.]([0-9]{1,2})[-/.]([0-9]{1,2})", t, re.ASCII)
    if m:
        return _iso(int(m.group(1)), int(m.group(2)), int(m.group(3))) or "INVALID"

    # Compact YYYYMMDD
    m = re.fullmatch(r"([0-9]{4})([0-9]{2})([0-9]{2})", t, re.ASCII)
    if m:
        return _iso(int(m.group(1)), int(m.group(2)), int(m.group(3))) or "INVALID"

    # Numeric with 4-digit year last: a/b/YYYY, a-b-YYYY, a.b.YYYY (day-first, month-first fallback)
    m = re.fullmatch(r"([0-9]{1,2})[-/.]([0-9]{1,2})[-/.]([0-9]{4})", t, re.ASCII)
    if m:
        return _numeric(m.group(1), m.group(2), m.group(3)) or "INVALID"

    # Month name first: "March 5, 2021", "Mar 5 2021", "March 5th, 2021", "Sept. 5, 2021"
    m = re.fullmatch(
        r"([A-Za-z]+)\.?\s+([0-9]{1,2})(?:st|nd|rd|th)?,?\s+([0-9]{4})",
        t, re.ASCII,
    )
    if m:
        mon = _month_num(m.group(1))
        if mon:
            return _iso(int(m.group(3)), mon, int(m.group(2))) or "INVALID"
        return "INVALID"

    # Day first with month name: "5 March 2021", "5th Mar, 2021", "5th of March 2021"
    m = re.fullmatch(
        r"([0-9]{1,2})(?:st|nd|rd|th)?\s+(?:of\s+)?([A-Za-z]+)\.?,?\s+([0-9]{4})",
        t, re.ASCII | re.IGNORECASE,
    )
    if m:
        mon = _month_num(m.group(2))
        if mon:
            return _iso(int(m.group(3)), mon, int(m.group(1))) or "INVALID"
        return "INVALID"

    return "INVALID"

import re
from datetime import date

_MONTHS = {
    "jan": 1, "january": 1,
    "feb": 2, "february": 2,
    "mar": 3, "march": 3,
    "apr": 4, "april": 4,
    "may": 5,
    "jun": 6, "june": 6,
    "jul": 7, "july": 7,
