    "sep": 9, "sept": 9, "september": 9,
    "oct": 10, "october": 10,
    "nov": 11, "november": 11,
    "dec": 12, "december": 12,
}

_WEEKDAY_PREFIX = re.compile(
    r"^(?:mon|tue|tues|wed|wednes|thu|thur|thurs|fri|sat|satur|sun)"
    r"(?:day)?\.?,?\s+"
)

_ISO = re.compile(r"(\d{4})[-/.](\d{1,2})[-/.](\d{1,2})")
_COMPACT = re.compile(r"(\d{4})(\d{2})(\d{2})")
_DMY_NUM = re.compile(r"(\d{1,2})[-/.](\d{1,2})[-/.](\d{4})")
_DAY_MON_YEAR = re.compile(r"(\d{1,2})(?:st|nd|rd|th)?\s+([a-z]+)\.?,?\s+(\d{4})")
_MON_DAY_YEAR = re.compile(r"([a-z]+)\.?\s+(\d{1,2})(?:st|nd|rd|th)?,?\s+(\d{4})")
_YEAR_MON_DAY = re.compile(r"(\d{4}),?\s+([a-z]+)\.?\s+(\d{1,2})(?:st|nd|rd|th)?")


def _build(y: int, m: int, d: int) -> str:
    try:
        return date(y, m, d).isoformat()
    except ValueError:
        return "INVALID"


def _month(name: str):
    return _MONTHS.get(name.rstrip("."))


def parse(s: str) -> str:
    if not isinstance(s, str):
        return "INVALID"

    t = re.sub(r"\s+", " ", s.strip()).lower()
    t = _WEEKDAY_PREFIX.sub("", t)
    if not t:
        return "INVALID"

    m = _ISO.fullmatch(t)
    if m:
        return _build(int(m[1]), int(m[2]), int(m[3]))

    m = _COMPACT.fullmatch(t)
    if m:
        return _build(int(m[1]), int(m[2]), int(m[3]))

    # Numeric dates are day-first: 29/02/2000 -> 2000-02-29.
    m = _DMY_NUM.fullmatch(t)
    if m:
        return _build(int(m[3]), int(m[2]), int(m[1]))

    m = _DAY_MON_YEAR.fullmatch(t)
    if m:
        mon = _month(m[2])
        if mon:
            return _build(int(m[3]), mon, int(m[1]))
        return "INVALID"

    m = _MON_DAY_YEAR.fullmatch(t)
    if m:
        mon = _month(m[1])
        if mon:
            return _build(int(m[3]), mon, int(m[2]))
        return "INVALID"

    m = _YEAR_MON_DAY.fullmatch(t)
    if m:
        mon = _month(m[2])
        if mon:
            return _build(int(m[1]), mon, int(m[3]))
        return "INVALID"

    return "INVALID"

import re
from datetime import date

_MONTH_NAMES = [
    "january", "february", "march", "april", "may", "june",
    "july", "august", "september", "october", "november", "december",
]
_MONTHS = {}
for _i, _name in enumerate(_MONTH_NAMES, start=1):
    _MONTHS[_name] = _i
    _MONTHS[_name[:3]] = _i
_MONTHS["sept"] = 9

# Optional weekday prefix, e.g. "Monday, " or "Tue "
_WD = r"(?:[a-z]+day,?\s+)?"
_ORD = r"(\d{1,2})(?:st|nd|rd|th)?"
_MON = r"([a-z]{3,9})\.?"
_YEAR = r"(\d{4})"

_RE_DMY_TEXT = re.compile(
    rf"^{_WD}{_ORD}(?:\s+of)?[\s\-/]+{_MON}[\s\-/,]+{_YEAR}$", re.IGNORECASE
)
_RE_MDY_TEXT = re.compile(
    rf"^{_WD}{_MON}[\s\-/]+{_ORD}[\s\-/,]+{_YEAR}$", re.IGNORECASE
)
_RE_ISO = re.compile(r"^(\d{4})[-/.](\d{1,2})[-/.](\d{1,2})$")
_RE_COMPACT = re.compile(r"^(\d{4})(\d{2})(\d{2})$")
_RE_NUMERIC = re.compile(r"^(\d{1,2})[-/.](\d{1,2})[-/.](\d{4})$")


def _format(year: int, month: int, day: int) -> str:
    """Return ISO date string, or 'INVALID' if the calendar date does not exist."""
    try:
        return date(year, month, day).isoformat()
    except ValueError:
        return "INVALID"


def _match_iso(t: str):
    m = _RE_ISO.match(t)
    if m:
        y, mo, d = (int(x) for x in m.groups())
        return _format(y, mo, d)
    return None


def _match_compact(t: str):
    m = _RE_COMPACT.match(t)
    if m:
        y, mo, d = (int(x) for x in m.groups())
        return _format(y, mo, d)
    return None


def _match_dmy_text(t: str):
    m = _RE_DMY_TEXT.match(t)
    if m:
        d, mon, y = m.groups()
        mo = _MONTHS.get(mon.lower())
        if mo is None:
            return "INVALID"
        return _format(int(y), mo, int(d))
    return None


def _match_mdy_text(t: str):
    m = _RE_MDY_TEXT.match(t)
    if m:
        mon, d, y = m.groups()
        mo = _MONTHS.get(mon.lower())
        if mo is None:
            return "INVALID"
        return _format(int(y), mo, int(d))
    return None


def _match_numeric(t: str):
    m = _RE_NUMERIC.match(t)
    if m:
        a, b, y = int(m.group(1)), int(m.group(2)), int(m.group(3))
        if a > 12 and b <= 12:
            day, month = a, b          # unambiguous: first field must be day
        elif b > 12 and a <= 12:
            month, day = a, b          # unambiguous: second field must be day
        else:
            day, month = a, b          # ambiguous: default to day-first
        return _format(y, month, day)
    return None


def parse(s: str) -> str:
    if not isinstance(s, str):
        return "INVALID"

    t = " ".join(s.strip().split())
    if not t:
        return "INVALID"

    for matcher in (
        _match_iso,
        _match_compact,
        _match_dmy_text,
        _match_mdy_text,
        _match_numeric,
    ):
        result = matcher(t)
        if result is not None:
            return result

    return "INVALID"

import re
import datetime

_MONTHS = {
    "jan": 1, "january": 1, "feb": 2, "february": 2, "mar": 3, "march": 3,
    "apr": 4, "april": 4, "may": 5, "jun": 6, "june": 6,
    "jul": 7, "july": 7, "aug": 8, "august": 8, "sep": 9, "sept": 9,
    "september": 9, "oct": 10, "october": 10, "nov": 11, "november": 11,
    "dec": 12, "december": 12,
}

_WEEKDAY_PREFIX = re.compile(
    r"^(?:mon|tue|tues|wed|wednes|thu|thur|thurs|fri|sat|sun)"
    r"(?:day)?\.?,?\s+",
    re.IGNORECASE,
)

_YMD_SEP = re.compile(r"(\d{4})([-/.])(\d{1,2})\2(\d{1,2})")
_YMD_COMPACT = re.compile(r"(\d{4})(\d{2})(\d{2})")
_NUM_SEP = re.compile(r"(\d{1,2})([-/.])(\d{1,2})\2(\d{4})")
_NAMED_MDY = re.compile(
    r"([A-Za-z]+)\.?\s+(\d{1,2})(?:st|nd|rd|th)?,?\s+(\d{4})"
)
_NAMED_DMY = re.compile(
    r"(\d{1,2})(?:st|nd|rd|th)?\s+([A-Za-z]+)\.?,?\s+(\d{4})"
)


def _make(year, month, day):
    """Return an ISO date string if the calendar date exists, else None."""
    try:
        return datetime.date(int(year), int(month), int(day)).isoformat()
    except (ValueError, OverflowError):
        return None


def _month_number(name):
    return _MONTHS.get(name.lower())


def _strip_weekday(text):
    """Remove a leading weekday name such as 'Tuesday, ' or 'Tue '."""
    return _WEEKDAY_PREFIX.sub("", text, count=1)


def _parse_numeric(t):
    m = _YMD_SEP.fullmatch(t)
    if m:
        return _make(m.group(1), m.group(3), m.group(4))

    m = _YMD_COMPACT.fullmatch(t)
    if m:
        return _make(m.group(1), m.group(2), m.group(3))

    m = _NUM_SEP.fullmatch(t)
    if m:
        first, second, year = int(m.group(1)), int(m.group(3)), m.group(4)
        # Day-first convention: read as DD<sep>MM<sep>YYYY when that is a
        # real calendar date; otherwise fall back to MM<sep>DD<sep>YYYY.
        result = _make(year, second, first)
        if result is None:
            result = _make(year, first, second)
        return result

    return None


def _parse_named(t):
    m = _NAMED_MDY.fullmatch(t)
    if m:
        month = _month_number(m.group(1))
        if month is not None:
            return _make(m.group(3), month, m.group(2))

    m = _NAMED_DMY.fullmatch(t)
    if m:
        month = _month_number(m.group(2))
        if month is not None:
            return _make(m.group(3), month, m.group(1))

    return None


def parse(s: str) -> str:
    if not isinstance(s, str):
        return "INVALID"
    t = s.strip()
    if not t:
        return "INVALID"

    # Accept an optional leading weekday name, e.g. "Tuesday, March 5, 2024".
    t = _strip_weekday(t).strip()
    if not t:
        return "INVALID"

    result = _parse_numeric(t)
    if result is None:
        result = _parse_named(t)

    return result if result is not None else "INVALID"
